from abc import ABC, abstractmethod

class DiscountStrategy(ABC):
    """
    This is a class that allows to use different discount strategy based on shopping credit or shopping cart in supermarket.
    """

    @abstractmethod
    def total(self):
        """Calculate the total cost of items in the cart."""
        pass

    @abstractmethod
    def due(self):
        """Calculate the final amount to be paid after applying the discount."""
        pass

    @staticmethod
    def FidelityPromo(order):
        """Calculate the discount based on the fidelity points of the customer."""
        if order.customer['fidelity'] >= 1000:
            return order.total() * 0.05
        return 0.0

    @staticmethod
    def BulkItemPromo(order):
        """Calculate the discount based on bulk item quantity in the order."""
        return sum(item['quantity'] * item['price'] * 0.1 if item['quantity'] >= 20 else 0 for item in order.cart)

    @staticmethod
    def LargeOrderPromo(order):
        """Calculate the discount based on the number of different products in the order."""
        return sum(1 for item in order.cart) >= 10

class Cart:
    def __init__(self, items):
        self.items = items

    def total(self):
        return sum(item['quantity'] * item['price'] for item in self.items)

class Order:
    def __init__(self, customer, cart, promotion):
        self.customer = customer
        self.cart = cart
        self.promotion = promotion

    def total(self):
        return self.cart.total()

    def due(self):
        discount = self.promotion(self)
        return self.total() - discount

# Example usage
if __name__ == "__main__":
    customer = {'name': 'John Doe', 'fidelity': 1200}
    cart = Cart([{'product': 'product', 'quantity': 14, 'price': 23.5}])
    order = Order(customer, cart, DiscountStrategy.FidelityPromo)
    print("Total:", order.total())
    print("Due:", order.due())
```

