            return False

        moves = {
            'w': (-1, 0),
            's': (1, 0),
            'a': (0, -1),
            'd': (0, 1)
        }

        new_row, new_col = self.player_row + moves[direction][0], self.player_col + moves[direction][1]

        if self.map[new_row][new_col] == '#':
            return False

        if (new_row, new_col) in self.boxes:
            new_box_row, new_box_col = new_row + moves[direction][0], new_col + moves[direction][1]

            if self.map[new_box_row][new_box_col] == '#':
                return False

            self.boxes = [(new_box_row, new_box_col) if (x, y) == (self.player_row, self.player_col) else (x, y) for x, y in self.boxes]
            self.boxes = [(new_row, new_col) if (x, y) == (self.player_row, self.player_col) else (x, y) for x, y in self.boxes]
            self.player_row, self.player_col = new_row, new_col
            return self.check_win()

        self.player_row, self.player_col = new_row, new_col
        return self.check_win()

    def print_map(self):
        for row in self.map:
