        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]


    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        def convert_to_int(tokens):
            total = 0
            prev_value = 0
            scale = 1

            for i, token in enumerate(tokens):
                if token.isdigit():
                    value = int(token)
                    total += value * prev_value * scale
                elif token in self.numwords:
                    num, weight = self.numwords[token]
                    total += num * prev_value * scale
                    prev_value = num
                elif token in self.scales:
                    scale *= self.numwords[token][0]
                    prev_value = 1
                elif token == 'and':
                    if i > 0:
                        prev_value *= 10
                else:
                    raise ValueError(f"Invalid token: {token}")

            return total

        def convert_to_units(tokens):
            converted = []
            for i, token in enumerate(tokens):
                if token in self.numwords:
                    num, weight = self.numwords[token]
                    if num > 1:
