                    else:
                        converted.append(self.units[num])
                elif token in self.scales:
                    converted.append(self.scales[i])
            return converted

        def convert_to_words(num):
            if num == 0:
                return ["zero"]
            words = []
            for i in range(len(self.scales) - 1, -1, -1):
                while num >= self.numwords[self.scales[i]][0]:
                    num -= self.numwords[self.scales[i]][0]
                    words.append(self.scales[i])
            return words

        def convert_to_ordinal(words):
            if words[-1] == "thousand":
                words[-1] = "thousandth"
            elif words[-1] == "million":
                words[-1] = "millionth"
            elif words[-1] == "billion":
                words[-1] = "billionth"
            elif words[-1] == "trillion":
                words[-1] = "trillionth"
            return words

        def process_text(textnum):
