        def convert_word_group(word_group):
            if "and" in word_group:
                parts = word_group.split(" and ")
                return convert_number(parts[0]) + convert_number(parts[1])
            else:
                parts = word_group.split()
                result = 0
                for i, word in enumerate(parts):
                    if word in self.numwords:
                        result += self.numwords[word][0]
                    elif word in self.ordinal_words:
                        result += self.ordinal_words[word]
                return result

        def convert_number(number_str):
            groups = number_str.split()
            result = 0
            i = 0
            while i < len(groups):
                group = groups[i]
                scale = None
                while i < len(groups) and groups[i].lower() in self.scales:
                    scale = self.scales[i]
                    i += 1
                if scale:
                    result += convert_word_group(group) * (10 ** (len(self.scales) - self.scales.index(scale)))
                else:
                    result += convert_word_group(group)
            return result

        if self.is_valid_input(textnum):
